    echo "Seeded custom_strategy.py (Smart Auto Pro + 15M SMC Sniper)."
else
    echo "Existing custom_strategy.py preserved."
fi

echo "=== [5/7] Setting up Python venv & installing dependencies ==="
if [ ! -d "$APP_DIR/venv" ]; then
    python3 -m venv "$APP_DIR/venv"
fi
"$APP_DIR/venv/bin/pip" install --upgrade pip
"$APP_DIR/venv/bin/pip" install flask werkzeug cryptography psycopg2-binary ccxt requests apscheduler gunicorn pysocks pandas numpy matplotlib websocket-client

echo "=== [6/7] Running syntax, database & import self-tests ==="
"$APP_DIR/venv/bin/python" -m py_compile "$APP_DIR/security.py" "$APP_DIR/db.py" "$APP_DIR/signal_parser.py" "$APP_DIR/exchange_adapters.py" "$APP_DIR/trade_engine.py" "$APP_DIR/templates_ui.py" "$APP_DIR/strategy_manager.py" "$APP_DIR/scanner.py" "$APP_DIR/kc_scanner_bp.py" "$APP_DIR/app.py" "$APP_DIR/custom_strategy.py"
KCT_DISABLE_SCHEDULER=1 KAVIAN_DISABLE_SCHEDULER=1 "$APP_DIR/venv/bin/python" -c 'import sys; sys.path.insert(0, "/opt/kaviancopytrade"); import app, db; ok1,e1,p1=app._validate_iran_phone("09123456789","+98"); ok2,e2,p2=app._validate_iran_phone("\u06f0\u06f9\u06f1\u06f2\u06f3\u06f4\u06f5\u06f6\u06f7\u06f8\u06f9","+98"); assert ok1 and p1=="+989123456789", f"EN phone failed: {ok1} {e1} {p1}"; assert ok2 and p2=="+989123456789", f"FA phone failed: {ok2} {e2} {p2}"; assert db.PAPER_BALANCE_MIN==100.0 and db.PAPER_BALANCE_MAX==10000.0, "Paper range mismatch"; print("SELF_TEST_OK | DB=" + db.get_db_engine() + " | PHONE_OK=" + p1 + " | PAPER_RANGE=100-10000 | ROUTES=" + str(len(list(app.app.url_map.iter_rules()))))'

echo "=== [7/7] Installing systemd service & 1-Click SSL helper ==="
cat << EOF_SERVICE > /etc/systemd/system/kaviancopytrade.service
[Unit]
Description=Kavian CopyTrade v3.9.2 Pro - Unified Copy-Trading Platform
After=network-online.target postgresql.service
Wants=network-online.target postgresql.service

[Service]
Type=simple
User=root
WorkingDirectory=$APP_DIR
EnvironmentFile=$APP_DIR/.env
ExecStart=$APP_DIR/venv/bin/gunicorn -w 1 --threads 8 --timeout 180 -b 0.0.0.0:$PORT app:app
Restart=always
RestartSec=5

[Install]
WantedBy=multi-user.target
EOF_SERVICE

cat << 'EOF_SSL_HELPER' > /usr/local/bin/kavian-copytrade-ssl
#!/bin/bash
set -e
DOMAIN="$1"
EMAIL="$2"
FLAG="${3:-}"
if [ -z "$DOMAIN" ] || [ -z "$EMAIL" ]; then
    echo "Usage: kavian-copytrade-ssl <your-domain.com> <your-email@domain.com>"
    exit 1
fi
echo "Configuring Nginx + Let's Encrypt HTTPS SSL for $DOMAIN ..."
cat << EOF_NGINX > /etc/nginx/sites-available/kaviancopytrade
server {
    listen 80;
    server_name $DOMAIN;

    client_max_body_size 25M;

    location / {
        proxy_pass http://127.0.0.1:8900;
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_read_timeout 180s;
    }
}
EOF_NGINX

ln -sf /etc/nginx/sites-available/kaviancopytrade /etc/nginx/sites-enabled/kaviancopytrade
nginx -t
systemctl enable nginx
systemctl reload nginx

if command -v ufw >/dev/null 2>&1; then
    ufw allow 80/tcp || true
    ufw allow 443/tcp || true
fi

certbot --nginx -d "$DOMAIN" --non-interactive --agree-tos -m "$EMAIL" --redirect

KCT_DISABLE_SCHEDULER=1 KAVIAN_DISABLE_SCHEDULER=1 /opt/kaviancopytrade/venv/bin/python - "$DOMAIN" << 'EOF_SET_DOM'
import sys
sys.path.insert(0, "/opt/kaviancopytrade")
import app, db
db.set_setting("public_domain", sys.argv[1])
print("Updated public_domain =", sys.argv[1])
EOF_SET_DOM

if [ "$FLAG" != "--no-restart" ]; then
    systemctl restart kaviancopytrade.service
fi
echo "========================================================"
echo "  HTTPS SSL Active: https://$DOMAIN"
echo "  Auto-renewal enabled via systemd certbot timer."
echo "========================================================"
EOF_SSL_HELPER
chmod +x /usr/local/bin/kavian-copytrade-ssl

systemctl daemon-reload
systemctl enable kaviancopytrade.service
systemctl restart kaviancopytrade.service
sleep 2

if command -v ufw >/dev/null 2>&1; then
    ufw allow $PORT/tcp || true
    ufw allow 80/tcp || true
    ufw allow 443/tcp || true
fi

if [ -n "$DOMAIN_ARG" ] && [ -n "$EMAIL_ARG" ]; then
    /usr/local/bin/kavian-copytrade-ssl "$DOMAIN_ARG" "$EMAIL_ARG"
fi

STATUS=$(systemctl is-active kaviancopytrade.service || true)
SERVER_IP=$(curl -s --max-time 5 https://api.ipify.org || hostname -I | awk '{print $1}')

echo ""
echo "========================================================"
echo "  Kavian CopyTrade v3.9.2 Pro Installation Complete!"
echo "  Service     : $STATUS"
echo "  Database    : PostgreSQL (kaviancopytrade)"
if [ -n "$DOMAIN_ARG" ]; then
echo "  Website URL : https://$DOMAIN_ARG"
else
echo "  Panel URL   : http://$SERVER_IP:$PORT"
echo "  SSL Setup   : Unified Admin -> System -> 1-Click SSL"
fi
echo "  Static IP   : $SERVER_IP (Inside Exchange Security Checklist)"
echo "  Admin Login : admin / admin12345  (Existing password preserved on upgrade)"
echo "========================================================"
